//! Reading and writing OPML subscription lists.

use mariner_feeds::opml::{self, OpmlError, Subscription};

const EXPORT: &str = r#"<?xml version="1.0" encoding="UTF-8"?>
<!-- OPML generated by Mariner -->
<opml version="1.1">
  <head>
    <title>Mariner Export</title>
  </head>
  <body>
    <outline text="9to5Google" title="9to5Google" description="" type="rss" version="RSS" htmlUrl="https://9to5google.com/feed" xmlUrl="https://9to5google.com/feed"/>
    <outline text="GamersNexus" title="GamersNexus" description="" type="rss" version="RSS" htmlUrl="https://gamersnexus.net/rss.xml" xmlUrl="https://gamersnexus.net/rss.xml"/>
    <outline text="Programming" title="Programming">
      <outline text="De Programmatica Ipsum" title="De Programmatica Ipsum" description="" type="rss" version="RSS" htmlUrl="https://deprogrammaticaipsum.com/feed" xmlUrl="https://deprogrammaticaipsum.com/feed"/>
      <outline text="R&amp;A Enterprise Architecture" title="R&amp;A Enterprise Architecture" description="" type="rss" version="RSS" htmlUrl="https://ea.rna.nl/feed/" xmlUrl="https://ea.rna.nl/feed/"/>
      <outline text="Ruby Weekly" title="Ruby Weekly" description="" type="rss" version="RSS" htmlUrl="https://cprss.s3.amazonaws.com/rubyweekly.com.xml" xmlUrl="https://cprss.s3.amazonaws.com/rubyweekly.com.xml"/>
    </outline>
    <outline text="Tech" title="Tech">
      <outline text="Ars Technica" title="Ars Technica" description="" type="rss" version="RSS" htmlUrl="https://feeds.arstechnica.com/arstechnica/index" xmlUrl="https://feeds.arstechnica.com/arstechnica/index"/>
      <outline text="The Verge" title="The Verge" description="" type="rss" version="RSS" htmlUrl="https://www.theverge.com/rss/index.xml" xmlUrl="https://www.theverge.com/rss/index.xml"/>
    </outline>
  </body>
</opml>
"#;

fn subscription(url: &str, title: &str, folders: &[&str]) -> Subscription {
    Subscription {
        feed_url: url.into(),
        title: Some(title.into()),
        site_url: None,
        folders: folders.iter().map(|folder| folder.to_string()).collect(),
    }
}

#[test]
fn reads_and_writes_the_same_document() {
    let subscriptions = opml::parse(EXPORT.as_bytes()).unwrap();
    assert_eq!(subscriptions.len(), 7);
    let entity = &subscriptions[3];
    assert_eq!(entity.title.as_deref(), Some("R&A Enterprise Architecture"));
    assert_eq!(entity.folders, ["Programming"]);
    assert_eq!(opml::write(&subscriptions), EXPORT);
}

#[test]
fn flattens_folders_and_lists_each_feed_once() {
    let document = r#"<opml version="2.0"><body>
        <outline title="News">
            <outline text="World">
                <outline text="A" xmlurl="https://a.example/feed"/>
            </outline>
            <outline text="B" xmlUrl="https://b.example/feed"/>
        </outline>
        <outline>
            <outline text="C" xmlUrl="https://c.example/feed"/>
        </outline>
        <outline text="Tech">
            <outline text="B again" xmlUrl="https://b.example/feed" htmlUrl="https://b.example/"/>
        </outline>
        <outline text="Empty"/>
        <outline text="No URL" type="rss"/>
    </body></opml>"#;
    let subscriptions = opml::parse(document.as_bytes()).unwrap();
    let mut b = subscription("https://b.example/feed", "B", &["News", "Tech"]);
    b.site_url = Some("https://b.example/".into());
    assert_eq!(
        subscriptions,
        [
            subscription("https://a.example/feed", "A", &["News"]),
            b,
            subscription("https://c.example/feed", "C", &[]),
        ],
        "nested folders go in the outermost, nameless ones pass feeds up, and a feed in \
         two folders is listed once with both"
    );
}

#[test]
fn writes_a_feed_in_each_of_its_folders() {
    let mut feed = subscription("https://b.example/feed", "B <&> \"Q\"", &["Tech", "News"]);
    feed.site_url = Some("https://b.example/".into());
    let written = opml::write(&[feed, subscription("https://a.example/feed", "a", &[])]);
    let lines: Vec<&str> = written.lines().map(str::trim).collect();
    let b = r#"<outline text="B &lt;&amp;&gt; &quot;Q&quot;" title="B &lt;&amp;&gt; &quot;Q&quot;" description="" type="rss" version="RSS" htmlUrl="https://b.example/" xmlUrl="https://b.example/feed"/>"#;
    assert_eq!(
        lines[7..],
        [
            r#"<outline text="a" title="a" description="" type="rss" version="RSS" htmlUrl="https://a.example/feed" xmlUrl="https://a.example/feed"/>"#,
            r#"<outline text="News" title="News">"#,
            b,
            "</outline>",
            r#"<outline text="Tech" title="Tech">"#,
            b,
            "</outline>",
            "</body>",
            "</opml>",
        ]
    );
    assert_eq!(opml::parse(written.as_bytes()).unwrap().len(), 2);
}

#[test]
fn refuses_what_isnt_opml() {
    assert!(matches!(
        opml::parse(b"<html><body>Hi</body></html>"),
        Err(OpmlError::NotOpml)
    ));
    assert!(matches!(
        opml::parse(b"<opml><body><outline text=\"A\"></body></opml>"),
        Err(OpmlError::Xml(_))
    ));
}
